            int unknown_var = -1;
            int unknown_count = 0;
            bool multiple_unknown_types = false;
            long long known_sum = 0;

            for (int i = 0; i < L; ++i) {
                int v = grid[i][j];
                if (solved[v]) {
                    known_sum += val[v];
                } else {
                    if (unknown_var == -1) {
                        unknown_var = v;
                        unknown_count = 1;
                    } else if (unknown_var == v) {
                        unknown_count++;
                    } else {
                        multiple_unknown_types = true;
                        break;
                    }
                }
            }

            if (!multiple_unknown_types && unknown_var != -1) {
                val[unknown_var] = (col_sum[j] - known_sum) / unknown_count;
                solved[unknown_var] = true;
                solved_count++;
                found = true;
                break;
            }
        }
    }

    for (int id = 0; id < 26 * 26; ++id) {
        if (present[id]) {
            char c1 = 'a' + id / 26;
            char c2 = 'a' + id % 26;
            cout << c1 << c2 << " " << val[id] << "\n";
        }
    }

    return 0;
}
